h1 { font-size: clamp(32px, 3.1vw, 46px); font-weight: 550; letter-spacing: -1.5px; line-height: 1.17; margin: 25px 0 18px; }
.welcome-copy p { font-size: 15px; line-height: 1.75; color: #83798f; margin: 0; }
.illustration { width: 440px; height: 350px; position: relative; align-self: center; margin: auto 0; flex-shrink: 0; z-index: 1; }
.orbit { border: 1px solid #d6c8eb; border-radius: 50%; position: absolute; top: 51%; left: 50%; transform: translate(-50%, -50%) rotate(-24deg); }
.orbit-outer { width: 414px; height: 287px; opacity: .55; }
