await expect(page.getByRole('checkbox',{name:'Запомнить меня'})).toBeChecked();
await page.locator('#password').press('Enter');
await expect(page.getByRole('status')).toContainText('Данные не отправлены');
await page.getByRole('button',{name:'Забыли пароль?'}).click();
await expect(page.getByRole('dialog')).toBeVisible();
await page.keyboard.press('Escape');
await expect(page.getByRole('dialog')).toHaveCount(0);
await page.reload({waitUntil:'networkidle'});
await page.screenshot({path:'/tmp/gravity-desktop.png',fullPage:true});
for(const width of [375,768,1024]) {
 await page.setViewportSize({width,height:812});
 if(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth)) throw Error('Horizontal overflow at '+width);
 await expect(page.getByRole('button',{name:'Войти',exact:true})).toBeVisible();
 if(width===375) await page.screenshot({path:'/tmp/gravity-mobile.png',fullPage:true});
}
if(errors.length) throw Error(errors.join('\\n'));
console.log('PASS: validation, password visibility, checkbox, Enter submission, modal dismissal, responsive widths 375/768/1024, no browser errors.');
await browser.close();
JS"

