const browser=await chromium.launch({channel:'chromium',headless:true,args:['--no-sandbox']});
const page=await browser.newPage({viewport:{width:1440,height:900}});
const errors=[]; page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://localhost:5175',{waitUntil:'networkidle'});
await page.getByRole('button',{name:'Войти',exact:true}).click();
await expect(page.getByText('Введите email',{exact:true})).toBeVisible();
await expect(page.locator('#email')).toBeFocused();
await page.locator('#email').fill('bad-email');
await expect(page.getByText('Введите корректный email')).toBeVisible();
await page.locator('#email').fill('hello@example.com');
await page.locator('#password').fill('test-password');
await page.getByRole('button',{name:'Показать пароль',exact:true}).click();
await expect(page.locator('#password')).toHaveAttribute('type','text');
await expect(page.getByRole('button',{name:'Скрыть пароль',exact:true})).toHaveAttribute('aria-pressed','true');
await page.getByRole('button',{name:'Скрыть пароль',exact:true}).click();
await expect(page.locator('#password')).toHaveAttribute('type','password');
await page.getByRole('checkbox',{name:'Запомнить меня'}).check();
await expect(page.getByRole('checkbox',{name:'Запомнить меня'})).toBeChecked();
await page.locator('#password').press('Enter');
await expect(page.getByRole('status')).toContainText('Данные не отправлены');
await page.getByRole('button',{name:'Забыли пароль?'}).click();
await expect(page.getByRole('dialog')).toBeVisible();
await page.keyboard.press('Escape');
await expect(page.getByRole('dialog')).toHaveCount(0);
await page.reload({waitUntil:'networkidle'});
await page.screenshot({path:'/tmp/gravity-desktop.png',fullPage:true});
for(const width of [375,768,1024]) {
 await page.setViewportSize({width,height:812});
 if(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth)) throw Error('Horizontal overflow at '+width);
 await expect(page.getByRole('button',{name:'Войти',exact:true})).toBeVisible();
 if(width===375) await page.screenshot({path:'/tmp/gravity-mobile.png',fullPage:true});
}
if(errors.length) throw Error(errors.join('\\n'));
console.log('PASS: validation, password visibility, checkbox, Enter submission, modal dismissal, responsive widths 375/768/1024, no browser errors.');
await browser.close();
JS"

